#include "SuitTypes.h"

namespace
{
	TArray<FSuitDef> BuildSuitTable()
	{
		TArray<FSuitDef> Out;
		// Generated by Tools/generate_suits_and_voices.py from suits.json. Each block is:
		//   { FSuitDef S; S.Id = ...; ...; Out.Add(S); }
#include "Generated/SuitTable.inl"
		if (Out.Num() == 0)
		{
			FSuitDef S;
			S.Id = TEXT("Mark3");
			S.Name = INVTEXT("Mark III");
			S.Mark = INVTEXT("MK III");
			Out.Add(S);
		}
		return Out;
	}

	TArray<FAIPersonaDef> BuildPersonaTable()
	{
		TArray<FAIPersonaDef> Out;
		auto Add = [&Out](EAIPersona P, const TCHAR* Label, FLinearColor Sub, FLinearColor Tint, const TCHAR* Folder, const TCHAR* Voice)
		{
			FAIPersonaDef D;
			D.Persona = P;
			D.Label = FText::AsCultureInvariant(FString(Label));
			D.SubtitleColor = Sub;
			D.HudTint = Tint;
			D.AudioFolder = Folder;
			D.VoiceDescription = Voice;
			Out.Add(D);
		};
		// Order must match EAIPersona.
		Add(EAIPersona::Jarvis,     TEXT("JARVIS"),         FLinearColor(0.55f, 0.85f, 1.f),  FLinearColor(0.35f, 0.8f, 1.f),   TEXT("JARVIS"),     TEXT("British male, dry butler wit"));
		Add(EAIPersona::Friday,     TEXT("FRIDAY"),         FLinearColor(1.f, 0.75f, 0.45f),  FLinearColor(1.f, 0.62f, 0.3f),   TEXT("FRIDAY"),     TEXT("Irish-ish female, warm and quick"));
		Add(EAIPersona::Edith,      TEXT("EDITH"),          FLinearColor(0.7f, 1.f, 0.75f),   FLinearColor(0.45f, 1.f, 0.6f),   TEXT("EDITH"),      TEXT("Crisp tactical female"));
		Add(EAIPersona::Ultron,     TEXT("ULTRON"),         FLinearColor(1.f, 0.25f, 0.2f),   FLinearColor(1.f, 0.12f, 0.08f),  TEXT("ULTRON"),     TEXT("Deep, menacing, pitched down"));
		Add(EAIPersona::WarMachine, TEXT("WAR MACHINE OS"), FLinearColor(0.85f, 0.88f, 0.9f), FLinearColor(0.75f, 0.8f, 0.82f), TEXT("WARMACHINE"), TEXT("Clipped US military"));
		return Out;
	}
}

const TArray<FSuitDef>& USuitLibrary::GetAllSuits()
{
	static const TArray<FSuitDef> Suits = BuildSuitTable();
	return Suits;
}

const FSuitDef& USuitLibrary::GetSuit(int32 Index)
{
	const TArray<FSuitDef>& All = GetAllSuits();
	return All[FMath::Clamp(Index, 0, All.Num() - 1)];
}

int32 USuitLibrary::FindSuitIndex(FName Id)
{
	const TArray<FSuitDef>& All = GetAllSuits();
	for (int32 i = 0; i < All.Num(); ++i)
	{
		if (All[i].Id == Id) { return i; }
	}
	return INDEX_NONE;
}

int32 USuitLibrary::GetNumSuits()
{
	return GetAllSuits().Num();
}

const FAIPersonaDef& USuitLibrary::GetPersona(EAIPersona Persona)
{
	static const TArray<FAIPersonaDef> Personas = BuildPersonaTable();
	const int32 Index = FMath::Clamp(static_cast<int32>(Persona), 0, Personas.Num() - 1);
	return Personas[Index];
}
